package avl

//----------------------------------------
// Node

// Node represents a node in an AVL tree.
type Node struct {
	key       string // key is the unique identifier for the node.
	value     any    // value is the data stored in the node.
	height    int8   // height is the height of the node in the tree.
	size      int    // size is the number of leaf nodes (key-value pairs) in the subtree rooted at this node.
	leftNode  *Node  // leftNode is the left child of the node.
	rightNode *Node  // rightNode is the right child of the node.
}

// NewNode creates a new node with the given key and value.
func NewNode(key string, value any) *Node {
	return &Node{
		key:    key,
		value:  value,
		height: 0,
		size:   1,
	}
}

// Size returns the size of the subtree rooted at the node.
func (node *Node) Size() int {
	if node == nil {
		return 0
	}
	return node.size
}

// IsLeaf checks if the node is a leaf node (has no children).
func (node *Node) IsLeaf() bool {
	return node.height == 0
}

// Key returns the key of the node.
func (node *Node) Key() string {
	return node.key
}

// Value returns the value of the node.
func (node *Node) Value() any {
	return node.value
}

func (node *Node) _copy() *Node {
	if node.height == 0 {
		panic("Why are you copying a value node?")
	}
	return &Node{
		key:       node.key,
		height:    node.height,
		size:      node.size,
		leftNode:  node.leftNode,
		rightNode: node.rightNode,
	}
}

// Has checks if a node with the given key exists in the subtree rooted at the node.
func (node *Node) Has(key string) (has bool) {
	if node == nil {
		return false
	}
	if node.key == key {
		return true
	}
	if node.height == 0 {
		return false
	} else {
		if key < node.key {
			return node.getLeftNode().Has(key)
		} else {
			return node.getRightNode().Has(key)
		}
	}
}

// Get searches for a node with the given key in the subtree rooted at the node
// and returns its index, value, and whether it exists.
func (node *Node) Get(key string) (index int, value any, exists bool) {
	if node == nil {
		return 0, nil, false
	}

	if node.height == 0 {
		if node.key == key {
			return 0, node.value, true
		} else if node.key < key {
			return 1, nil, false
		} else {
			return 0, nil, false
		}
	} else {
		if key < node.key {
			return node.getLeftNode().Get(key)
		} else {
			rightNode := node.getRightNode()
			index, value, exists = rightNode.Get(key)
			index += node.size - rightNode.size
			return index, value, exists
		}
	}
}

// GetByIndex retrieves the key-value pair of the node at the given index
// in the subtree rooted at the node.
func (node *Node) GetByIndex(index int) (key string, value any) {
	if index < 0 {
		panic("GetByIndex: negative index not allowed")
	}

	if node.height == 0 {
		if index != 0 {
			panic("GetByIndex asked for invalid index")
		}
		return node.key, node.value
	} else {
		// TODO: could improve this by storing the sizes
		leftNode := node.getLeftNode()
		if index < leftNode.size {
			return leftNode.GetByIndex(index)
		} else {
			return node.getRightNode().GetByIndex(index - leftNode.size)
		}
	}
}

// Set inserts a new node with the given key-value pair into the subtree rooted at the node,
// and returns the new root of the subtree and whether an existing node was updated.
//
// XXX consider a better way to do this... perhaps split Node from Node.
func (node *Node) Set(key string, value any) (newSelf *Node, updated bool) {
	if node == nil {
		return NewNode(key, value), false
	}
	if node.height == 0 {
		if key < node.key {
			return &Node{
				key:       node.key,
				height:    1,
				size:      2,
				leftNode:  NewNode(key, value),
				rightNode: node,
			}, false
		} else if key == node.key {
			return NewNode(key, value), true
		} else {
			return &Node{
				key:       key,
				height:    1,
				size:      2,
				leftNode:  node,
				rightNode: NewNode(key, value),
			}, false
		}
	} else {
		node = node._copy()
		if key < node.key {
			node.leftNode, updated = node.getLeftNode().Set(key, value)
		} else {
			node.rightNode, updated = node.getRightNode().Set(key, value)
		}
		if updated {
			return node, updated
		} else {
			node.calcHeightAndSize()
			return node.balance(), updated
		}
	}
}

// Remove deletes the node with the given key from the subtree rooted at the node.
// returns the new root of the subtree, the new leftmost leaf key (if changed),
// the removed value and the removal was successful.
func (node *Node) Remove(key string) (
	newNode *Node, newKey string, value any, removed bool,
) {
	if node == nil {
		return nil, "", nil, false
	}
	if node.height == 0 {
		if key == node.key {
			return nil, "", node.value, true
		} else {
			return node, "", nil, false
		}
	} else {
		if key < node.key {
			var newLeftNode *Node
			newLeftNode, newKey, value, removed = node.getLeftNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newLeftNode == nil { // left node held value, was removed
				return node.rightNode, node.key, value, true
			}
			node = node._copy()
			node.leftNode = newLeftNode
			node.calcHeightAndSize()
			node = node.balance()
			return node, newKey, value, true
		} else {
			var newRightNode *Node
			newRightNode, newKey, value, removed = node.getRightNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newRightNode == nil { // right node held value, was removed
				return node.leftNode, "", value, true
			}
			node = node._copy()
			node.rightNode = newRightNode
			if newKey != "" {
				node.key = newKey
			}
			node.calcHeightAndSize()
			node = node.balance()
			return node, "", value, true
		}
	}
}

func (node *Node) getLeftNode() *Node {
	return node.leftNode
}

func (node *Node) getRightNode() *Node {
	return node.rightNode
}

// rotateRight performs a right rotation on the node and returns the new root.
// NOTE: overwrites node
// TODO: optimize balance & rotate
func (node *Node) rotateRight() *Node {
	node = node._copy()
	l := node.getLeftNode()
	_l := l._copy()

	_lrCached := _l.rightNode
	_l.rightNode = node
	node.leftNode = _lrCached

	node.calcHeightAndSize()
	_l.calcHeightAndSize()

	return _l
}

// rotateLeft performs a left rotation on the node and returns the new root.
// NOTE: overwrites node
// TODO: optimize balance & rotate
func (node *Node) rotateLeft() *Node {
	node = node._copy()
	r := node.getRightNode()
	_r := r._copy()

	_rlCached := _r.leftNode
	_r.leftNode = node
	node.rightNode = _rlCached

	node.calcHeightAndSize()
	_r.calcHeightAndSize()

	return _r
}

// calcHeightAndSize updates the height and size of the node based on its children.
// NOTE: mutates height and size
func (node *Node) calcHeightAndSize() {
	node.height = maxInt8(node.getLeftNode().height, node.getRightNode().height) + 1
	node.size = node.getLeftNode().size + node.getRightNode().size
}

// calcBalance calculates the balance factor of the node.
func (node *Node) calcBalance() int {
	return int(node.getLeftNode().height) - int(node.getRightNode().height)
}

// balance balances the subtree rooted at the node and returns the new root.
// NOTE: assumes that node can be modified
// TODO: optimize balance & rotate
func (node *Node) balance() (newSelf *Node) {
	balance := node.calcBalance()
	if balance > 1 {
		if node.getLeftNode().calcBalance() >= 0 {
			// Left Left Case
			return node.rotateRight()
		} else {
			// Left Right Case
			left := node.getLeftNode()
			node.leftNode = left.rotateLeft()
			return node.rotateRight()
		}
	}
	if balance < -1 {
		if node.getRightNode().calcBalance() <= 0 {
			// Right Right Case
			return node.rotateLeft()
		} else {
			// Right Left Case
			right := node.getRightNode()
			node.rightNode = right.rotateRight()
			return node.rotateLeft()
		}
	}
	// Nothing changed
	return node
}

// Shortcut for TraverseInRange.
func (node *Node) Iterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, true, true, cb)
}

// Shortcut for TraverseInRange.
func (node *Node) ReverseIterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, false, true, cb)
}

// TraverseInRange traverses all nodes, including inner nodes.
// Start is inclusive and end is exclusive when ascending,
// Start and end are inclusive when descending.
// Empty start and empty end denote no start and no end.
// If leavesOnly is true, only visit leaf nodes.
// NOTE: To simulate an exclusive reverse traversal,
// just append 0x00 to start.
func (node *Node) TraverseInRange(start, end string, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}
	afterStart := (start == "" || start < node.key)
	startOrAfter := (start == "" || start <= node.key)
	beforeEnd := false
	if ascending {
		beforeEnd = (end == "" || node.key < end)
	} else {
		beforeEnd = (end == "" || node.key <= end)
	}

	// Run callback per inner/leaf node.
	stop := false
	if (!node.IsLeaf() && !leavesOnly) ||
		(node.IsLeaf() && startOrAfter && beforeEnd) {
		stop = cb(node)
		if stop {
			return stop
		}
	}
	if node.IsLeaf() {
		return stop
	}

	if ascending {
		// check lower nodes, then higher
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	} else {
		// check the higher nodes first
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	}

	return stop
}

// TraverseByOffset traverses all nodes, including inner nodes.
// A limit of math.MaxInt means no limit.
func (node *Node) TraverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}

	// Clamp negative offset to 0; otherwise `delta := first.size - offset`
	// over-counts and silently drops nodes.
	if offset < 0 {
		offset = 0
	}

	// fast paths. these happen only if TraverseByOffset is called directly on a leaf.
	if limit <= 0 || offset >= node.size {
		return false
	}
	if node.IsLeaf() {
		if offset > 0 {
			return false
		}
		return cb(node)
	}

	// go to the actual recursive function.
	return node.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

// TraverseByOffset traverses the subtree rooted at the node by offset and limit,
// in either ascending or descending order, and applies the callback function to each traversed node.
// If leavesOnly is true, only leaf nodes are visited.
func (node *Node) traverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	// caller guarantees: offset < node.size; limit > 0.
	if !leavesOnly {
		if cb(node) {
			return true // Stop traversal if callback returns true
		}
	}
	first, second := node.getLeftNode(), node.getRightNode()
	if !ascending {
		first, second = second, first
	}
	if first.IsLeaf() {
		// either run or skip, based on offset
		if offset > 0 {
			offset--
		} else {
			if cb(first) {
				return true // Stop traversal if callback returns true
			}
			limit--
			if limit <= 0 {
				return true // Stop traversal when limit is reached
			}
		}
	} else {
		// possible cases:
		// 1 the offset given skips the first node entirely
		// 2 the offset skips none or part of the first node, but the limit requires some of the second node.
		// 3 the offset skips none or part of the first node, and the limit stops our search on the first node.
		if offset >= first.size {
			offset -= first.size // 1
		} else {
			if first.traverseByOffset(offset, limit, ascending, leavesOnly, cb) {
				return true
			}
			// number of leaves which could actually be called from inside
			delta := first.size - offset
			offset = 0
			if delta >= limit {
				return true // 3
			}
			limit -= delta // 2
		}
	}

	// because of the caller guarantees and the way we handle the first node,
	// at this point we know that limit > 0 and there must be some values in
	// this second node that we include.

	// => if the second node is a leaf, it has to be included.
	if second.IsLeaf() {
		return cb(second)
	}
	// => if it is not a leaf, it will still be enough to recursively call this
	// function with the updated offset and limit
	return second.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

// Only used in testing...
func (node *Node) lmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getLeftNode().lmd()
}

// Only used in testing...
func (node *Node) rmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getRightNode().rmd()
}

func maxInt8(a, b int8) int8 {
	if a > b {
		return a
	}
	return b
}

// Package avl is a vendored copy of gno.land/p/nt/avl/v0, pinned under
// this project's own namespace instead of imported from the shared
// stdlib. Necessary because that shared package is NOT the same across
// gno.land networks: testnet's Tree.Get returns a single value (any),
// while Beta Mainnet's already returns two (value any, exists bool) —
// confirmed directly from each chain's own deployed source, not
// documentation. Code built against one signature fails to compile on
// the other, so this project can't depend on the shared import staying
// consistent across every network it deploys to. Vendoring under our
// own address means every deploy — local, testnet, Beta Mainnet, or
// wherever gno.land goes next — gets the exact same, single-return
// Get() this project's code (the messages realm) is written against,
// regardless of whatever the shared package looks like on that chain.
//
// Copied verbatim from gno.land/p/nt/avl/v0 (testnet's version, single-
// return Get) as of 2026-08 — not reimplemented, to avoid introducing
// any behavioral drift from the tested original. Same copy already
// vendored under this project's Gems collection
// (gno.land/p/g17cjym5e9hhws46lt6329pv2gtx2ay0503hgems/avl).
package avl

type ITree interface {
	// read operations

	Size() int
	Has(key string) bool
	Get(key string) any
	GetByIndex(index int) (key string, value any)
	Iterate(start, end string, cb IterCbFn) bool
	ReverseIterate(start, end string, cb IterCbFn) bool
	IterateByOffset(offset int, count int, cb IterCbFn) bool
	ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool

	// write operations

	Set(key string, value any) (updated bool)
	Remove(key string) (value any, removed bool)
}

type IterCbFn func(key string, value any) bool

//----------------------------------------
// Tree

// The zero struct can be used as an empty tree.
type Tree struct {
	node *Node
}

// NewTree creates a new empty AVL tree.
func NewTree() *Tree {
	return &Tree{
		node: nil,
	}
}

// Size returns the number of key-value pair in the tree.
func (tree *Tree) Size() int {
	return tree.node.Size()
}

// Has checks whether a key exists in the tree.
// It returns true if the key exists, otherwise false.
func (tree *Tree) Has(key string) (has bool) {
	return tree.node.Has(key)
}

// Get retrieves the value associated with the given key.
// It returns the value if the key exists, or nil if it doesn't.
// Note that a key stored with a nil value is indistinguishable
// from an absent key; use Has to check for existence.
// This allows for a simpler usage pattern with type assertions:
//
//	if value, ok := tree.Get("key").(MyType); ok {
//	    // use value
//	}
func (tree *Tree) Get(key string) any {
	_, value, _ := tree.node.Get(key)
	return value
}

// GetByIndex retrieves the key-value pair at the specified index in the tree.
// It returns the key and value at the given index.
func (tree *Tree) GetByIndex(index int) (key string, value any) {
	return tree.node.GetByIndex(index)
}

// Set inserts a key-value pair into the tree.
// If the key already exists, the value will be updated.
// It returns a boolean indicating whether the key was newly inserted or updated.
func (tree *Tree) Set(key string, value any) (updated bool) {
	newnode, updated := tree.node.Set(key, value)
	tree.node = newnode
	return updated
}

// Remove removes a key-value pair from the tree.
// It returns the removed value and a boolean indicating whether the key was found and removed.
func (tree *Tree) Remove(key string) (value any, removed bool) {
	newnode, _, value, removed := tree.node.Remove(key)
	tree.node = newnode
	return value, removed
}

// Iterate performs an in-order traversal of the tree within the specified key range.
// It calls the provided callback function for each key-value pair encountered.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) Iterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// ReverseIterate performs a reverse in-order traversal of the tree within the specified key range.
// It calls the provided callback function for each key-value pair encountered.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) ReverseIterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// IterateByOffset performs an in-order traversal of the tree starting from the specified offset.
// It calls the provided callback function for each key-value pair encountered, up to the specified count.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) IterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// ReverseIterateByOffset performs a reverse in-order traversal of the tree starting from the specified offset.
// It calls the provided callback function for each key-value pair encountered, up to the specified count.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// Verify that Tree implements TreeInterface
var _ ITree = (*Tree)(nil)

// Package messages implements "Onchain Messages" — a public, fully
// threaded on-chain guestbook. Anyone posts a message to a shared public
// board; anyone can reply to any message, arbitrarily deep. There is no
// recipient/target field — this is a public wall, not private messaging
// (gno.land has no encryption anyway, so a "to" field would only ever be
// a label, never real privacy). Any address can look up every direct
// reply to everything IT has authored — its "inbox" — computed
// incrementally at Post-time (see inboxByAuthor below), never joined
// from messages+repliesByParent at read time, so an inbox lookup stays
// cheap regardless of how many messages or replies someone has
// accumulated.
//
// Design mirrors this project's existing nftminter.gno realm (Gems)
// throughout: pipe-delimited/base64 summary lines, page-based pagination
// windowing that returns "" past the last page rather than clamping
// (Gems' own CollectionSummary already behaves this way — the clamping
// Gems does elsewhere is Render()'s own human-gnoweb-browsing
// convenience, a separate concern this realm doesn't need for v1), and
// the same avl.Tree/seqid.ID/callerAddress() plumbing.
//
// Deploy identity: g1lyuc4zhnmd7dkdvt02fmzq9q0drqmgtn2t00ls -- both this
// package and its sibling gno.land/p/<addr>/avl declare their module path
// under that address. See DEPLOY.md in this folder for the deploy
// checklist itself.
package messages

import (
	"encoding/base64"
	"errors"
	"strings"

	runtime "chain/runtime"
	unsaferealm "chain/runtime/unsafe"

	"gno.land/p/g1lyuc4zhnmd7dkdvt02fmzq9q0drqmgtn2t00ls/avl"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// MaxMessageLen caps a single message's text. Storage-deposit cost
	// scales with data size, and this board has no moderation/edit path,
	// so a hard cap keeps a single bad post cheap to store and cheap for
	// every downstream page (feed/replies/inbox) to render. 1000 chars is
	// long enough for a real paragraph, short enough that a page of
	// pageSize messages stays small.
	MaxMessageLen = 1000

	// pageSize is how many rows FeedSummary/RepliesSummary/InboxSummary
	// return per call. Text-only storage here is far cheaper per row
	// than Gems' on-the-fly SVG generation (see nftminter.gno's own
	// homeRenderLimit doc comment for why THAT constant had to be tuned
	// down from 50 to 10), so one shared constant across all three lists
	// is enough for v1.
	pageSize = 20

	// maxParentChainDepth bounds ParentChainSummary's walk-to-root.
	// Threads nest arbitrarily deep by design (fully threaded replies),
	// so an unbounded walk here would reintroduce the exact "unbounded
	// on-chain work" trap Gems' own CollectionSummary hit before it was
	// paginated — this is a defensive ceiling, not an expected real depth.
	maxParentChainDepth = 100
)

// Message is one post — top-level or a reply, no structural difference
// between the two beyond ParentID.
type Message struct {
	ID            uint64
	Author        address
	Text          string
	ParentID      uint64 // 0 = top-level; never a real message's own ID (see Post)
	CreatedHeight int64
	ReplyCount    int64 // direct replies only, kept in sync at Post-time
}

var (
	// nextID assigns message IDs. Post calls Next() FIRST and uses the
	// already-advanced value (unlike nftminter.gno's own nextID, read
	// BEFORE Next() advances it) — deliberately, so ID 0 stays
	// permanently unassigned and can serve as ParentID's "no parent /
	// top-level" sentinel without ever colliding with a real message.
	nextID seqid.ID

	// messages holds every message ever posted, top-level and replies
	// alike, keyed by its own ID.
	messages avl.Tree // seqid.ID(id).String() -> Message

	// topLevelIDs is every top-level (ParentID==0) message ID, oldest
	// first — same shape as nftminter.gno's mintedIDs. FeedSummary walks
	// this backward for newest-first pagination.
	topLevelIDs []uint64

	// repliesByParent indexes each message's own direct replies in post
	// order. The local index is read from the parent's OWN ReplyCount
	// field right before Post increments it — a 0-based position among
	// that parent's replies specifically, not a global ID. RepliesSummary
	// does a direct windowed Get() per row against this, no scanning.
	repliesByParent avl.Tree // parentID.String()+":"+seqid.ID(localIdx).String() -> uint64 (childID)

	// inboxCountByAuthor / inboxByAuthor together are the actual "my
	// inbox" index — same windowed shape as repliesByParent, but
	// bucketed by the REPLIED-TO message's OWN author, not by the
	// specific parent message. Populated incrementally inside Post by
	// looking up the parent's Author once, at write time — InboxSummary
	// never joins messages+repliesByParent at read time.
	inboxCountByAuthor avl.Tree // author.String() -> int64
	inboxByAuthor       avl.Tree // author.String()+":"+seqid.ID(localIdx).String() -> uint64 (replyID)
)

// callerAddress derives the address that crossed into this realm, same
// one-line helper nftminter.gno itself uses (see that file's own doc
// comment on why unsaferealm.PreviousRealm() rather than cur.Previous()).
func callerAddress() address {
	return unsaferealm.PreviousRealm().Address()
}

func getMessage(id uint64) (Message, bool) {
	raw := messages.Get(seqid.ID(id).String())
	msg, ok := raw.(Message)
	return msg, ok
}

// messageSummaryLine mirrors nftminter.gno's own TokenSummary shape:
// pipe-delimited fields, only the free-text field base64-encoded.
func messageSummaryLine(msg Message) string {
	fields := []string{
		ufmt.Sprintf("%d", msg.ID),
		msg.Author.String(),
		ufmt.Sprintf("%d", msg.ParentID),
		ufmt.Sprintf("%d", msg.CreatedHeight),
		ufmt.Sprintf("%d", msg.ReplyCount),
		base64.StdEncoding.EncodeToString([]byte(msg.Text)),
	}
	return strings.Join(fields, "|")
}

// Post creates a new message. parentID == 0 means a top-level post;
// any other value must name an existing message, and the new message
// becomes a direct reply to it — arbitrarily deep threading is just
// replies-to-replies, no special casing needed beyond this.
func Post(cur realm, text string, parentID uint64) uint64 {
	if len(text) == 0 {
		panic("message text cannot be empty")
	}
	if len(text) > MaxMessageLen {
		panic(ufmt.Sprintf("message exceeds the %d-character limit", MaxMessageLen))
	}

	var parentAuthor address
	var parentKey string
	var localReplyIdx int64
	if parentID != 0 {
		parentKey = seqid.ID(parentID).String()
		raw := messages.Get(parentKey)
		parent, ok := raw.(Message)
		if !ok {
			panic(ufmt.Sprintf("parent message %d does not exist", parentID))
		}
		parentAuthor = parent.Author
		localReplyIdx = parent.ReplyCount
		parent.ReplyCount++
		messages.Set(parentKey, parent)
	}

	id := uint64(nextID.Next()) // advance-first: see nextID's own doc comment above
	msg := Message{
		ID:            id,
		Author:        callerAddress(),
		Text:          text,
		ParentID:      parentID,
		CreatedHeight: runtime.ChainHeight(),
	}
	messages.Set(seqid.ID(id).String(), msg)

	if parentID == 0 {
		topLevelIDs = append(topLevelIDs, id)
	} else {
		repliesByParent.Set(parentKey+":"+seqid.ID(uint64(localReplyIdx)).String(), id)

		inboxIdx, _ := inboxCountByAuthor.Get(parentAuthor.String()).(int64)
		inboxByAuthor.Set(parentAuthor.String()+":"+seqid.ID(uint64(inboxIdx)).String(), id)
		inboxCountByAuthor.Set(parentAuthor.String(), inboxIdx+1)
	}
	return id
}

// MessageCount is every message ever posted, top-level and replies alike.
func MessageCount() int64 {
	return int64(messages.Size())
}

// FeedCount is how many top-level messages exist — what FeedSummary
// paginates over.
func FeedCount() int64 {
	return int64(len(topLevelIDs))
}

// FeedSummary returns page's worth of top-level messages, newest-first.
// page < 1 clamps to 1; a page past the end returns "" (not clamped to
// the last real page — see this file's own top doc comment on why).
func FeedSummary(page int) string {
	total := len(topLevelIDs)
	if page < 1 {
		page = 1
	}
	startK := (page - 1) * pageSize
	endK := startK + pageSize
	if endK > total {
		endK = total
	}
	var lines []string
	for k := startK; k < endK; k++ {
		id := topLevelIDs[total-1-k] // k=0 is newest
		msg, ok := getMessage(id)
		if !ok {
			continue
		}
		lines = append(lines, messageSummaryLine(msg))
	}
	return strings.Join(lines, "\n")
}

// ReplyCount is how many DIRECT replies msgID has.
func ReplyCount(msgID uint64) int64 {
	msg, ok := getMessage(msgID)
	if !ok {
		return 0
	}
	return msg.ReplyCount
}

// RepliesSummary returns page's worth of msgID's DIRECT replies,
// oldest-first (a conversation reads top-to-bottom) — cheaper than
// FeedSummary's own newest-first walk, since repliesByParent's local
// index is already assigned in post order, so this is a direct forward
// windowed Get() with no reversal arithmetic.
func RepliesSummary(msgID uint64, page int) string {
	parent, ok := getMessage(msgID)
	if !ok {
		return ""
	}
	total := int(parent.ReplyCount)
	if page < 1 {
		page = 1
	}
	startK := (page - 1) * pageSize
	endK := startK + pageSize
	if endK > total {
		endK = total
	}
	parentKey := seqid.ID(msgID).String()
	var lines []string
	for k := startK; k < endK; k++ {
		raw := repliesByParent.Get(parentKey + ":" + seqid.ID(uint64(k)).String())
		childID, ok := raw.(uint64)
		if !ok {
			continue
		}
		child, ok := getMessage(childID)
		if !ok {
			continue
		}
		lines = append(lines, messageSummaryLine(child))
	}
	return strings.Join(lines, "\n")
}

// MessageSummary is one message's own detail line (for a permalink/
// thread view showing a single node in isolation).
func MessageSummary(msgID uint64) (string, error) {
	msg, ok := getMessage(msgID)
	if !ok {
		return "", errors.New(ufmt.Sprintf("message %d does not exist", msgID))
	}
	return messageSummaryLine(msg), nil
}

// ParentChainSummary returns msgID's ancestor chain, oldest-ancestor-
// first — e.g. for a grandchild reply, [top-level, its reply]. Empty if
// msgID doesn't exist or is itself top-level. Bounded by
// maxParentChainDepth (see that const's own doc comment).
func ParentChainSummary(msgID uint64) string {
	msg, ok := getMessage(msgID)
	if !ok {
		return ""
	}
	var lines []string
	cur := msg
	depth := 0
	for cur.ParentID != 0 && depth < maxParentChainDepth {
		parent, ok := getMessage(cur.ParentID)
		if !ok {
			break
		}
		lines = append(lines, messageSummaryLine(parent))
		cur = parent
		depth++
	}
	// lines is currently immediate-parent-first (youngest ancestor
	// first) — reverse for the documented oldest-ancestor-first order.
	for i, j := 0, len(lines)-1; i < j; i, j = i+1, j-1 {
		lines[i], lines[j] = lines[j], lines[i]
	}
	return strings.Join(lines, "\n")
}

// InboxCount is how many replies exist across every message owner has
// ever authored.
func InboxCount(owner address) int64 {
	raw := inboxCountByAuthor.Get(owner.String())
	n, ok := raw.(int64)
	if !ok {
		return 0
	}
	return n
}

// InboxSummary returns page's worth of replies to everything owner has
// authored, newest-first — the "my inbox" view. Uses the same
// newest-first reversal as FeedSummary, against inboxByAuthor's own
// append-order local index (see that var's own doc comment).
func InboxSummary(owner address, page int) string {
	total := int(InboxCount(owner))
	if page < 1 {
		page = 1
	}
	startK := (page - 1) * pageSize
	endK := startK + pageSize
	if endK > total {
		endK = total
	}
	ownerKey := owner.String()
	var lines []string
	for k := startK; k < endK; k++ {
		localIdx := total - 1 - k // k=0 is newest
		raw := inboxByAuthor.Get(ownerKey + ":" + seqid.ID(uint64(localIdx)).String())
		replyID, ok := raw.(uint64)
		if !ok {
			continue
		}
		reply, ok := getMessage(replyID)
		if !ok {
			continue
		}
		lines = append(lines, messageSummaryLine(reply))
	}
	return strings.Join(lines, "\n")
}
